'use client';

/**
 * @file CheckboxRowPressContext.ts
 * @input Uses the private layer-scoped context factory
 * @output CheckboxRowPressContext: whether the row is its checkbox's press surface
 * @position Internal; CheckboxListItem provides it, CheckboxInput reads it
 *
 * Such a row carries the shared press marker (utils/pressFeedback.ts). Its
 * checkbox carries none, so a finger anywhere on the row presses the row.
 * It is layer-scoped and wraps only the row's own checkbox.
 *
 * SYNC: When modified, update CheckboxInput.tsx and
 * ../CheckboxList/CheckboxListItem.tsx.
 */

import {createLayerScopedContext} from '../Layer/layerScopedContext';

export const CheckboxRowPressContext = createLayerScopedContext(
  'CheckboxRowPressContext',
  1,
  false,
);
CheckboxRowPressContext.displayName = 'CheckboxRowPressContext';

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file CheckboxList.tsx
 * @input Uses React, useId, useOptimistic, useTransition, Field, List, CheckboxListContext, requiredGroup
 * @output Exports CheckboxList component, CheckboxListProps
 * @position Core implementation; consumed by index.ts, tested by CheckboxList.test.tsx
 *
 * SYNC: When modified, update these files to stay in sync:
 * - /packages/core/src/CheckboxList/CheckboxList.doc.mjs
 * - /packages/core/src/CheckboxList/CheckboxList.test.tsx
 * - /packages/core/src/CheckboxList/index.ts
 * - /apps/storybook/stories/CheckboxList.stories.tsx
 * - /packages/cli/assets/templates/blocks/components/CheckboxList/ (showcase blocks)
 */

import {
  useCallback,
  useId,
  useMemo,
  useOptimistic,
  useTransition,
  type ReactNode,
} from 'react';
import type {FieldInputBaseProps} from '@astryxdesign/core/Field';
import {useFieldInputStyling} from '../Field/fieldParts';
import {useMergedRefs} from '@astryxdesign/core/hooks';
import type {SizeValue} from '@astryxdesign/core/utils';
import {Field} from '@astryxdesign/core/Field';
import type {InputStatus} from '@astryxdesign/core/Field';
import {List} from '@astryxdesign/core/List';
import type {ListDensity} from '@astryxdesign/core/List';
import {useTooltip} from '@astryxdesign/core/Tooltip';
import * as stylex from '@stylexjs/stylex';
import {mergeProps} from '@astryxdesign/core/utils';
import {themeProps} from '@astryxdesign/core/utils';
import {joinAriaIDs} from '../utils/inputAria';
import {
  CheckboxListContext,
  type CheckboxListContextValue,
} from './CheckboxListContext';
import {createRequiredGroup} from './requiredGroup';

const EMPTY_ARRAY: string[] = [];

export interface CheckboxListProps extends Omit<
  FieldInputBaseProps<HTMLDivElement>,
  'onChange'
> {
  /** Ref forwarded to the `role="group"` element. */
  ref?: React.Ref<HTMLDivElement>;
  /**
   * Label text for the checkbox group (always rendered for accessibility).
   */
  label: string;
  /**
   * Whether to visually hide the label (still accessible to screen readers).
   * @default false
   */
  isLabelHidden?: boolean;
  /**
   * Description text displayed below the label.
   */
  description?: string;
  /**
   * Whether the group is optional. Shows the optional indicator after the
   * group label, unless a surrounding `FormLayout` already makes fields
   * optional by default.
   * @default false
   */
  isOptional?: boolean;
  /**
   * Whether the group needs at least one checked box. Shows the required
   * indicator after the group label by the same rules as every input field.
   * While no box is checked, the browser blocks submit and moves focus to
   * the first box that is neither disabled nor read-only. A disabled or
   * read-only group requires nothing. Show your own error text through
   * `status`.
   * Mutually exclusive with isOptional.
   * @default false
   */
  isRequired?: boolean;
  /**
   * Status indicator for the checkbox group.
   * When set with a message, displays a colored message box below the group.
   */
  status?: InputStatus;
  /**
   * The currently selected values (collection mode).
   */
  value?: string[];
  /**
   * Callback fired when the selected values change (collection mode).
   */
  onChange?: (values: string[]) => void;
  /**
   * Async action on change. Fires after onChange.
   * While the returned promise is pending, the toggled item shows a spinner
   * inside its checkbox and is marked `aria-busy`, and re-toggling it is
   * blocked. Other items remain interactive.
   */
  changeAction?: (values: string[]) => void | Promise<void>;
  /**
   * Spacing density for list items.
   * @default 'balanced'
   */
  density?: ListDensity;
  /**
   * Whether to show dividers between list items.
   * @default false
   */
  hasDividers?: boolean;
  /**
   * Whether all checkbox items are disabled.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Explains why the checkbox group is disabled. Applies to the whole-group
   * disabled state (`isDisabled`), not individual items. When set together with
   * `isDisabled`, the group shows a tooltip with this text on hover and keyboard
   * focus, and its checkboxes stay focusable (via `aria-disabled`) so the reason
   * is discoverable by keyboard and assistive technology. Toggling stays
   * blocked.
   *
   * Use this instead of wrapping a disabled group in `Tooltip` — disabled
   * controls don't emit the pointer events an external tooltip needs.
   */
  disabledMessage?: string;
  /**
   * Whether all checkbox items are read-only.
   * Displays the current state at full opacity but prevents interaction.
   * Unlike `isDisabled`, read-only checkboxes are not visually dimmed.
   * @default false
   */
  isReadOnly?: boolean;
  /**
   * Width of the field. Numbers are treated as pixels, strings are used as-is
   * (e.g. `'100%'`). Sizes the whole field (label, control, and status) so they
   * stay aligned, unlike setting width via `xstyle`/`className`/`style`.
   */
  width?: SizeValue;
  /**
   * Checkbox list items to render.
   */
  children: ReactNode;
}

/**
 * A checkbox group component for multi-value selection.
 *
 * Composes Field (for label, description, status) and List
 * (for density, dividers) with a context provider for collection mode.
 *
 * @example
 * ```
 * <CheckboxList
 *   label="Notifications"
 *   value={selected}
 *   onChange={setSelected}>
 *   <CheckboxListItem label="Email" value="email" />
 *   <CheckboxListItem label="SMS" value="sms" />
 *   <CheckboxListItem label="Push" value="push" />
 * </CheckboxList>
 * ```
 */
export function CheckboxList({
  label,
  isLabelHidden = false,
  description,
  isOptional = false,
  isRequired = false,
  status,
  value,
  onChange,
  changeAction,
  density = 'balanced',
  hasDividers = false,
  isDisabled = false,
  disabledMessage,
  isReadOnly = false,
  children,
  ref,
  width,
  containerXstyle,
  containerClassName,
  containerStyle,
  controlXstyle,
  controlClassName,
  controlStyle,
  'aria-labelledby': ariaLabelledByProp,
  'aria-describedby': ariaDescribedByProp,
  ...restProps
}: CheckboxListProps) {
  const {rest, container} = useFieldInputStyling('CheckboxList', restProps, {
    containerXstyle,
    containerClassName,
    containerStyle,
  });
  const inputID = useId();
  const labelID = useId();
  const descriptionID = useId();
  const statusMessageID = useId();

  const requiredGroup = useMemo(
    () => (isRequired ? createRequiredGroup() : undefined),
    [isRequired],
  );
  const observeRequiredGroup = useCallback(
    (container: HTMLDivElement | null) =>
      container != null && requiredGroup != null
        ? requiredGroup.observe(container)
        : undefined,
    [requiredGroup],
  );

  const [, startTransition] = useTransition();
  const isCollectionMode = value !== undefined;
  const effectiveValue = value ?? EMPTY_ARRAY;
  const [optimisticValue, setOptimisticValue] = useOptimistic(effectiveValue);
  // Values whose `changeAction` is pending. React settles concurrent
  // transitions together, so each toggled value stays listed until they all
  // finish, then reverts to empty without manual cleanup.
  const [loadingValues, addLoadingValue] = useOptimistic<
    ReadonlyArray<string>,
    string
  >(EMPTY_ARRAY, (pending, toggled) =>
    pending.includes(toggled) ? pending : [...pending, toggled],
  );

  // Disabled-reason tooltip. Applies to the whole-group disabled state. Disabled
  // controls swallow pointer events, so the tooltip listeners attach to the
  // group container and the checkboxes stay perceivable via aria-disabled
  // instead of the disabled attribute. Toggling is blocked in the item. The
  // reason describes the group and each checkbox (see
  // CheckboxListContextValue.disabledMessageID).
  const showsDisabledMessage = isDisabled && !!disabledMessage;
  const disabledMessageTooltip = useTooltip({
    placement: 'above',
    // The group container is not naturally focusable; focusin bubbles up from
    // the checkboxes, so always attach focus listeners.
    focusTrigger: 'always',
    isEnabled: showsDisabledMessage,
  });

  const handleChange = useCallback(
    (newValues: string[], toggledValue?: string) => {
      onChange?.(newValues);
      if (changeAction) {
        startTransition(async () => {
          setOptimisticValue(newValues);
          if (toggledValue !== undefined) {
            addLoadingValue(toggledValue);
          }
          await changeAction(newValues);
        });
      }
    },
    [
      onChange,
      changeAction,
      startTransition,
      setOptimisticValue,
      addLoadingValue,
    ],
  );

  const contextValue = useMemo<CheckboxListContextValue>(
    () => ({
      value: isCollectionMode ? optimisticValue : undefined,
      onChange: isCollectionMode ? handleChange : undefined,
      isDisabled,
      hasDisabledMessage: showsDisabledMessage,
      disabledMessageID: showsDisabledMessage
        ? disabledMessageTooltip.describedBy
        : undefined,
      isReadOnly,
      isInvalid: status?.type === 'error',
      loadingValues,
      requiredGroup,
    }),
    [
      isCollectionMode,
      optimisticValue,
      handleChange,
      isDisabled,
      showsDisabledMessage,
      disabledMessageTooltip.describedBy,
      isReadOnly,
      status?.type,
      loadingValues,
      requiredGroup,
    ],
  );

  return (
    <Field
      label={label}
      isLabelHidden={isLabelHidden}
      description={description}
      inputID={inputID}
      labelID={labelID}
      isGroupLabel
      isOptional={isOptional}
      isRequired={isRequired}
      descriptionID={description ? descriptionID : undefined}
      isDisabled={isDisabled}
      status={
        status
          ? {
              type: status.type,
              message: status.message,
              messageID: status.message ? statusMessageID : undefined,
            }
          : undefined
      }
      statusVariant="detached"
      width={width}
      xstyle={container.xstyle}
      {...mergeProps(themeProps('checkbox-list'), {
        className: container.className,
        style: container.style,
      })}>
      <CheckboxListContext value={contextValue}>
        <div
          {...rest}
          // The disabled-message tooltip anchors here; its handlers are gated
          // internally by isEnabled, so attaching unconditionally is safe.
          ref={useMergedRefs(
            ref,
            disabledMessageTooltip.ref,
            observeRequiredGroup,
          )}
          {...mergeProps(
            stylex.props(controlXstyle),
            controlClassName,
            controlStyle,
          )}
          role="group"
          // Screen readers announce the whole group as unavailable. Its dimmed
          // label then labels a disabled control. An enabled list keeps a
          // caller's own value.
          aria-disabled={isDisabled || rest['aria-disabled']}
          // A caller aria-labelledby names the group together with its label.
          aria-labelledby={joinAriaIDs(labelID, ariaLabelledByProp)}
          aria-describedby={
            [
              ariaDescribedByProp,
              description ? descriptionID : null,
              status?.message ? statusMessageID : null,
              showsDisabledMessage ? disabledMessageTooltip.describedBy : null,
            ]
              .filter(Boolean)
              .join(' ') || undefined
          }>
          <List density={density} hasDividers={hasDividers}>
            {children}
          </List>
        </div>
      </CheckboxListContext>
      {showsDisabledMessage &&
        disabledMessageTooltip.renderTooltip(disabledMessage)}
    </Field>
  );
}

CheckboxList.displayName = 'CheckboxList';

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file CheckboxListContext.tsx
 * @input Uses the private layer-scoped context factory and the RequiredGroup
 *   type
 * @output Exports CheckboxListContext for parent-child communication
 * @position Internal context; consumed by CheckboxList.tsx and CheckboxListItem.tsx
 */

import {createLayerScopedContext} from '../Layer/layerScopedContext';
import type {RequiredGroup} from './requiredGroup';

export interface CheckboxListContextValue {
  value?: string[];
  /**
   * Collection-mode change handler. `toggledValue` is the value of the item
   * the user just toggled, so the list can show a loading spinner on that
   * specific item while a `changeAction` promise is pending — no diffing
   * of the value array required.
   */
  onChange?: (values: string[], toggledValue?: string) => void;
  isDisabled: boolean;
  /**
   * True when the whole group is disabled *and* a `disabledMessage` is set. In
   * that mode items stay focusable via `aria-disabled` (instead of the native
   * `disabled` attribute) so the group's disabled-reason tooltip is keyboard-
   * and AT-discoverable; toggling is still blocked.
   */
  hasDisabledMessage?: boolean;
  /**
   * The id of the group's reason tooltip while `hasDisabledMessage` is true.
   * The reason describes the group (CheckboxList FR1) and every checkbox adds
   * it to its own `aria-describedby` (FR9): a screen reader announces a
   * checkbox's description when the checkbox takes focus, which it does not
   * reliably do for a description on the group.
   */
  disabledMessageID?: string;
  isReadOnly: boolean;
  /**
   * True when the list has an error `status`. Each checkbox is then
   * `aria-invalid`. Some screen readers skip a group's invalid state when a
   * checkbox takes focus.
   */
  isInvalid?: boolean;
  /**
   * Values of the items whose `changeAction` is pending. Each matching item
   * renders an in-checkbox spinner and blocks re-toggling; the list is empty
   * when idle.
   */
  loadingValues?: ReadonlyArray<string>;
  /**
   * Present when the list is `isRequired`. Each item registers its checkbox,
   * so that while no box is checked the first enabled box carries native
   * `required`.
   */
  requiredGroup?: RequiredGroup;
}

export const CheckboxListContext =
  createLayerScopedContext<CheckboxListContextValue | null>(
    'CheckboxListContext',
    1,
    null,
  );
CheckboxListContext.displayName = 'CheckboxListContext';

// Copyright (c) Meta Platforms, Inc. and affiliates.

'use client';

/**
 * @file CheckboxListItem.tsx
 * @input Uses React, CheckboxInput, ListItem, CheckboxListContext,
 *   CheckboxRowPressContext, the touch presentation and the row press paint
 * @output Exports CheckboxListItem component, CheckboxListItemProps
 * @position Core implementation; consumed by index.ts, tested by CheckboxList.test.tsx
 *
 * SYNC: When modified, update these files to stay in sync:
 * - /packages/core/src/CheckboxList/CheckboxListItem.doc.mjs
 * - /packages/core/src/CheckboxList/CheckboxList.doc.mjs
 * - /packages/core/src/CheckboxList/CheckboxList.test.tsx
 * - /packages/core/src/CheckboxList/index.ts
 * - /apps/storybook/stories/CheckboxList.stories.tsx
 * - /packages/cli/assets/templates/blocks/components/CheckboxList/ (showcase blocks)
 */

import {use, useCallback, useId, useRef, type ReactNode} from 'react';
import * as stylex from '@stylexjs/stylex';
import type {StyleXStyles} from '@stylexjs/stylex';
import {colorVars} from '@astryxdesign/core/theme/tokens.stylex';
import type {BaseProps} from '@astryxdesign/core/BaseProps';
import {CheckboxInput} from '@astryxdesign/core/CheckboxInput';
import type {CheckboxInputProps} from '@astryxdesign/core/CheckboxInput';
import type {InputStatus} from '@astryxdesign/core/Field';
import {CheckboxRowPressContext} from '../CheckboxInput/CheckboxRowPressContext';
import {rowPressPaintStyles} from '../privateAttributes/press.stylex';
import {interactionOverlayStyles} from '@astryxdesign/core/utils/interactionOverlay.stylex';
import {useTouchPresentation} from '../utils/touchPresentation';
import {ListItem} from '@astryxdesign/core/List';
import {ListContext} from '../List/ListContext';
import {CheckboxListContext} from './CheckboxListContext';
import {ItemDescriptionContext} from '../Item/ItemDescriptionContext';
import {joinAriaIDs} from '../utils/inputAria';
import {useMergedRefs} from '@astryxdesign/core/hooks';
import {themeDataAttributes} from '@astryxdesign/core/utils';
import type {ItemAlign} from '@astryxdesign/core/Item';
import {registerEnglishFallback} from '../i18n/englishFallback';
import {useComponentTranslator} from '../i18n/useComponentTranslator';
import english from '../i18n/generated-english/CheckboxList/CheckboxListItem.generated';

registerEnglishFallback(english);

// =============================================================================
// Styles
// =============================================================================

const styles = stylex.create({
  selected: {
    backgroundColor: colorVars['--color-accent-muted'],
  },
});

// =============================================================================
// Types
// =============================================================================

export interface CheckboxListItemProps extends BaseProps<HTMLLIElement> {
  /**
   * Vertical alignment of the start and end content against the label,
   * forwarded to Item. Use `first-line` to keep the checkbox level with the
   * first line of a wrapped label.
   * @default 'center'
   */
  align?: ItemAlign;
  /**
   * Primary text label for the item.
   *
   * Accepts a plain string (single-line truncation applied automatically)
   * or a ReactNode for rich content (no truncation constraints —
   * child components control their own text behavior). Links and buttons in
   * the label keep their own behavior; only non-interactive row clicks
   * delegate to the checkbox.
   *
   * A string names the checkbox directly. A ReactNode names it from its
   * visible text through `aria-labelledby`; if that text is absent, pass
   * `aria-label`. When visible text is present, an override must retain every
   * visible word so speech-input users can say what they see.
   */
  label: ReactNode;
  /**
   * Plain-text accessible name for the checkbox, replacing the one derived
   * from `label`.
   *
   * A string `label` names the checkbox directly, and a rich (ReactNode)
   * `label` names it from its visible text through `aria-labelledby`. Pass
   * `aria-label` when that text is absent. When visible text is present, the
   * override must retain every visible word so speech-input users can say what
   * they see. It replaces the derived name and applies to the checkbox control,
   * not the row.
   *
   * @example
   * ```
   * <CheckboxListItem
   *   label={<span>Pro plan <Badge label="Recommended" /></span>}
   *   aria-label="Pro plan Recommended option"
   *   value="pro"
   * />
   * ```
   */
  'aria-label'?: string;
  /**
   * Identity key for collection mode. Required when the parent CheckboxList
   * has a `value` array: the item throws without it there. An item inside
   * List, or inside a CheckboxList without `value`, may omit it.
   */
  value?: string;
  /**
   * Secondary content below the label. Accepts a plain string or a ReactNode.
   * Exposed as the checkbox's accessible description through
   * `aria-describedby`, so assistive technology can tell it is the explanation
   * for this choice rather than unrelated row text.
   */
  description?: ReactNode;
  /**
   * Content rendered after the label area.
   */
  endContent?: ReactNode;
  /**
   * Whether this individual item is disabled.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Whether this item is in a loading state. Renders a spinner inside the
   * checkbox and blocks interaction on this item only.
   *
   * In collection mode, this is also driven automatically: when the parent
   * `CheckboxList` has a `changeAction`, the toggled item shows its
   * spinner while that promise is pending.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Direct checked state for standalone mode: an item inside List, or inside
   * a CheckboxList without `value` (for example, a select-all item). Ignored
   * when the parent CheckboxList has a `value` array, which then owns the
   * checked state.
   */
  isChecked?: boolean | 'indeterminate';
  /**
   * Direct check handler for standalone mode: an item inside List, or inside a
   * CheckboxList without `value`. Ignored when the parent CheckboxList has a
   * `value` array; that list's `onChange` receives the change instead.
   */
  onCheck?: (checked: boolean) => void;
  /** Ref forwarded to the root element */
  ref?: React.Ref<HTMLLIElement>;
}

// =============================================================================
// Component
// =============================================================================

const ERROR_STATUS: InputStatus = {type: 'error'};

/**
 * The row's visible description is the checkbox's accessible description. Item
 * renders that element and owns its id, and publishes the id through
 * ItemDescriptionContext; this reads it from inside the slot Item renders. The
 * row cannot wrap the description in an id'd element instead — that turns a
 * plain string into a ReactNode and drops the single-line truncation ListItem
 * documents — and a public `descriptionId` prop would fail
 * `spec:AST-002/DEC-1`, since the caller decides nothing Item cannot derive.
 *
 * This component owns `aria-describedby`, so the prop is omitted rather than
 * accepted and overwritten: a caller passing one would otherwise lose the id
 * silently. After the row's description comes the group's disabled reason
 * (CheckboxList's disabledMessage), which describes each checkbox (FR9).
 */
function DescribedCheckboxInput(
  props: Omit<CheckboxInputProps, 'aria-describedby'>,
) {
  const describedBy = use(ItemDescriptionContext);
  const listContext = use(CheckboxListContext);
  return (
    <CheckboxInput
      {...props}
      aria-describedby={joinAriaIDs(
        describedBy ?? undefined,
        listContext?.disabledMessageID,
      )}
      // The status has no message, so CheckboxInput renders nothing. The list
      // renders the message.
      status={listContext?.isInvalid ? ERROR_STATUS : undefined}
    />
  );
}

/**
 * A checkbox item for use within CheckboxList (collection mode, when the list
 * has a `value` array) or standalone (inside List, or inside a CheckboxList
 * without `value`).
 *
 * In collection mode, checked state is derived from the parent's value array.
 * In standalone mode, uses isChecked/onCheck props directly.
 *
 * Composes ListItem internally — gets density, dividers, hover/press,
 * focus, and container alignment for free.
 *
 * @example
 * ```
 * <CheckboxListItem label="Email" value="email" />
 * <CheckboxListItem
 *   label="Accept terms"
 *   isChecked={accepted}
 *   onCheck={setAccepted}
 * />
 * ```
 */
export function CheckboxListItem({
  label,
  'aria-label': ariaLabel,
  value,
  description,
  endContent,
  isDisabled: isItemDisabled = false,
  isLoading: isItemLoading = false,
  isChecked,
  onCheck,
  ref,
  xstyle,
  className,
  style,
  onClick: onClickProp,
  align,
  ...restProps
}: CheckboxListItemProps) {
  const t = useComponentTranslator();
  const ctx = use(CheckboxListContext);

  if (ctx && ctx.value !== undefined && value === undefined) {
    throw new Error(
      'CheckboxListItem requires a `value` prop when used inside CheckboxList with a value array.',
    );
  }

  // Accessible name for the checkbox. A string `label` (or an explicit
  // `aria-label`) becomes the text of CheckboxInput's visually hidden
  // `<label>`, which only accepts a string. A rich label instead names the
  // checkbox from the visible label element through `aria-labelledby`, as
  // RadioListItem does; the hidden label then carries only the generic word,
  // which `aria-labelledby` outranks. Strings are left unwrapped on purpose:
  // Item single-line-truncates a raw string label but not a node.
  const isRichLabel = typeof label !== 'string';
  const labelID = useId();
  const namesFromVisibleLabel = isRichLabel && ariaLabel == null;

  const checkboxLabel =
    ariaLabel ??
    (isRichLabel ? t('@astryx.checkboxList.item.checkbox') : label);

  // Density from list context for checkbox sizing
  const listCtx = use(ListContext);
  const density = listCtx?.density ?? 'balanced';
  const checkboxSize = density === 'compact' ? 'sm' : 'md';

  // Disabled: parent-level OR item-level
  const effectiveDisabled = (ctx?.isDisabled ?? false) || isItemDisabled;
  const effectiveReadOnly = ctx?.isReadOnly ?? false;
  // Loading is per-item: explicit item prop OR (collection mode) an item
  // whose `changeAction` is currently pending in the parent.
  const isBusy =
    isItemLoading ||
    (value !== undefined && (ctx?.loadingValues?.includes(value) ?? false));

  // Resolve checked state:
  // 1. Collection mode (inside CheckboxList with value[])
  // 2. Standalone mode (isChecked prop)
  // 3. Neither → unchecked
  let resolvedChecked: boolean | 'indeterminate' = false;
  if (ctx && ctx.value !== undefined && value !== undefined) {
    resolvedChecked = ctx.value.includes(value);
  } else if (isChecked !== undefined) {
    resolvedChecked = isChecked;
  }

  // Whether this item is interactive (has a toggle handler)
  const isInteractive = !effectiveReadOnly && (ctx != null || onCheck != null);

  // The checkbox is the row's single keyboard control and action. The row is
  // an enlarged click/tap target that delegates surface clicks to it via
  // ListItem's `interactiveRef` (useClickableContainer), so each option is
  // exactly one tab stop. Delegate whenever the row should respond to clicks:
  // a toggleable item, or one carrying a consumer `onClick`.
  const checkboxRef = useRef<HTMLInputElement | null>(null);
  const hasRowInteraction = isInteractive || onClickProp != null;

  // A required group decides which box carries native `required` from the
  // state of every box. A change to this box's state registers it again.
  const requiredGroup = ctx?.requiredGroup;
  const isBoxChecked = resolvedChecked === true;
  const isBoxEnabled = !effectiveDisabled && !effectiveReadOnly;
  const registerWithRequiredGroup = useCallback(
    (input: HTMLInputElement | null) =>
      input != null && requiredGroup != null
        ? requiredGroup.register(input, {
            isChecked: isBoxChecked,
            isEnabled: isBoxEnabled,
          })
        : undefined,
    [requiredGroup, isBoxChecked, isBoxEnabled],
  );
