      left: x - MOUSE_OPENING_HALF_SIDE_PX,
      right: x + MOUSE_OPENING_HALF_SIDE_PX,
      top: y - MOUSE_OPENING_HALF_SIDE_PX,
      bottom: y + MOUSE_OPENING_HALF_SIDE_PX,
