    return false;
  }
  if (!entry.values.has(value)) {
    entry.values.add(value);
    entry.css += `:where([${TOUCH_ACTION_ATTRIBUTE}="${value}"]){touch-action:${value}}`;
    entry.write(`@layer ${RULE_LAYER}{${entry.css}}`);
