  kind: 'duration',
  text: string,
): number | null;
export function parseMotionRoleValue(
  kind: 'curve',
  text: string,
): MotionCurvePoints | null;
export function parseMotionRoleValue(
  kind: MotionRoleKind,
  text: string,
): DurationBounce | number | MotionCurvePoints | null;
