  if (m == null) {
    return null;
  }
  const points = [m[1], m[2], m[3], m[4]].map(Number) as unknown as [
    number,
    number,
    number,
    number,
  ];
  return points[0] >= 0 && points[0] <= 1 && points[2] >= 0 && points[2] <= 1
    ? points
    : null;
